import { test } from 'node:test';
import assert from 'node:assert/strict';
import { adicionarItem, buscarItemPorId, removerItemPorId } from './solution.mjs';

test('adiciona o primeiro item com id 1', () => {
  const lista = adicionarItem([], 'estudar Node');
  assert.deepEqual(lista, [{ id: 1, nome: 'estudar Node' }]);
});

test('continua a numeração a partir do maior id existente', () => {
  const lista = adicionarItem([{ id: 1, nome: 'estudar' }, { id: 2, nome: 'treinar' }], 'cozinhar');
  assert.equal(lista.length, 3);
  assert.deepEqual(lista[2], { id: 3, nome: 'cozinhar' });
});

test('busca um item pelo id e devolve undefined quando não existe', () => {
  const lista = [{ id: 1, nome: 'estudar' }];
  assert.deepEqual(buscarItemPorId(lista, 1), { id: 1, nome: 'estudar' });
  assert.equal(buscarItemPorId(lista, 99), undefined);
});

test('remove pelo id sem alterar a original, e lança erro nos casos errados', () => {
  const original = [{ id: 1, nome: 'estudar' }, { id: 2, nome: 'treinar' }];
  const resultado = removerItemPorId(original, 1);
  assert.deepEqual(resultado, [{ id: 2, nome: 'treinar' }]);
  assert.equal(original.length, 2); // a lista original não mudou
  assert.throws(() => removerItemPorId(original, 99), /não encontrado/);
  assert.throws(() => adicionarItem(original, '   '), /obrigatório/);
});

