// Lista de tarefas em memória — CRUD manual sobre um array.
// As três funções são PURAS: recebem a lista e devolvem um resultado novo,
// sem nunca alterar a lista que receberam.

// CRIAR: devolve uma lista nova com o item adicionado no fim.
// O id é automático: 1 na lista vazia, depois o maior id existente + 1.
export function adicionarItem(lista, nome) {
  if (typeof nome !== 'string' || nome.trim() === '') {
    throw new Error('nome é obrigatório');
  }
  const proximoId = lista.reduce((maior, item) => Math.max(maior, item.id), 0) + 1;
  return [...lista, { id: proximoId, nome }];
}

// LER: devolve o item com aquele id, ou undefined se não existir.
export function buscarItemPorId(lista, id) {
  return lista.find((item) => item.id === id);
}

// DELETAR: devolve uma lista nova SEM o item com aquele id.
// Lança erro se o id não existir.
export function removerItemPorId(lista, id) {
  const existe = lista.some((item) => item.id === id);
  if (!existe) {
    throw new Error(`item ${id} não encontrado`);
  }
  return lista.filter((item) => item.id !== id);
}
